import{_ as n,o as a,c as o,a2 as t}from"./chunks/framework.Boholvbs.js";const m=JSON.parse('{"title":"Dependency Maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"dev/dependency-maintenance/index.md","filePath":"dev/dependency-maintenance.md"}'),i={name:"dev/dependency-maintenance/index.md"};function d(r,e,c,s,l,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="dependency-maintenance" tabindex="-1">Dependency Maintenance <a class="header-anchor" href="#dependency-maintenance" aria-label="Permalink to &quot;Dependency Maintenance&quot;">​</a></h1><p>JEO uses GitHub-native dependency maintenance for routine updates and keeps custom repository logic limited to plugin-specific release and runtime checks.</p><h2 id="automated-maintenance" tabindex="-1">Automated maintenance <a class="header-anchor" href="#automated-maintenance" aria-label="Permalink to &quot;Automated maintenance&quot;">​</a></h2><ul><li>Dependabot opens weekly pull requests against <code>develop</code> for npm, Composer, and GitHub Actions updates.</li><li>Dependency Review runs on pull requests and fails when a dependency change introduces a high-severity vulnerability or worse.</li><li><code>npm audit --package-lock-only</code> and <code>composer audit --locked</code> remain the local commands for checking the current lockfiles.</li></ul><h2 id="reviewing-update-pull-requests" tabindex="-1">Reviewing update pull requests <a class="header-anchor" href="#reviewing-update-pull-requests" aria-label="Permalink to &quot;Reviewing update pull requests&quot;">​</a></h2><ol><li>Check whether the update is a patch, minor, major, or GitHub Action change.</li><li>Review the Dependency Review result for newly introduced advisories.</li><li>Run the relevant local checks: <ul><li>npm or frontend update: <code>npm ci</code>, <code>npm run build</code>, <code>npm run build:report</code>, and <code>npm run test:unit</code>.</li><li>PHP or Composer update: <code>composer install</code>, <code>composer audit --locked</code>, <code>vendor/bin/phpcs --standard=phpcs.xml.dist</code>, and <code>vendor/bin/phpcs --standard=phpcs-compat.xml.dist</code>.</li><li>Runtime-sensitive update: run the WordPress smoke test or wait for the WordPress Smoke Tests workflow.</li></ul></li><li>For major updates, confirm the editor, map, story map, Discovery, geocoding, and public rendering flows touched by the package still behave correctly.</li></ol><h2 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to &quot;Overrides&quot;">​</a></h2><p>The <code>overrides</code> block in <code>package.json</code> is reserved for temporary security, compatibility, or local-package pins. Each override should be removed when the upstream dependency no longer needs it.</p><p>When adding or changing an override, include the reason and the removal condition in the pull request description. Revisit active overrides after major <code>@wordpress/scripts</code>, Gutenberg, React, or webpack updates.</p>',9)])])}const h=n(i,[["render",d]]);export{m as __pageData,h as default};
